-- Full Schema Export from CayTheDB
-- Generated: 2026-06-10T09:02:56.896Z

USE ShopDonkDB;
GO

-- Table: Banners
IF EXISTS (SELECT * FROM sysobjects WHERE name='Banners' AND xtype='U') DROP TABLE Banners;
CREATE TABLE Banners (
  id int IDENTITY(1,1) NOT NULL,
  title nvarchar(200) NOT NULL,
  description nvarchar(500) NULL,
  image nvarchar(500) NOT NULL,
  link nvarchar(500) NULL,
  active bit NULL DEFAULT ((1)),
  display_order int NULL DEFAULT ((0)),
  created_at datetime NULL DEFAULT (getdate()),
  updated_at datetime NULL,
  PRIMARY KEY (id)
);
GO

-- Table: Categories
IF EXISTS (SELECT * FROM sysobjects WHERE name='Categories' AND xtype='U') DROP TABLE Categories;
CREATE TABLE Categories (
  id int IDENTITY(1,1) NOT NULL,
  name nvarchar(100) NOT NULL,
  slug nvarchar(50) NOT NULL,
  icon nvarchar(50) NULL,
  color nvarchar(20) NULL,
  image nvarchar(MAX) NULL,
  description nvarchar(500) NULL,
  created_at datetime NULL DEFAULT (getdate()),
  updated_at datetime NULL,
  PRIMARY KEY (id)
);
GO

-- Table: Images
IF EXISTS (SELECT * FROM sysobjects WHERE name='Images' AND xtype='U') DROP TABLE Images;
CREATE TABLE Images (
  id int IDENTITY(1,1) NOT NULL,
  public_id nvarchar(500) NOT NULL,
  url nvarchar(1000) NOT NULL,
  original_name nvarchar(255) NULL,
  size int NULL,
  width int NULL,
  height int NULL,
  format nvarchar(20) NULL,
  resource_type nvarchar(50) NULL DEFAULT ('image'),
  user_id int NULL,
  created_at datetime NULL DEFAULT (getdate()),
  PRIMARY KEY (id)
);
GO

-- Table: Orders
IF EXISTS (SELECT * FROM sysobjects WHERE name='Orders' AND xtype='U') DROP TABLE Orders;
CREATE TABLE Orders (
  id int IDENTITY(1,1) NOT NULL,
  user_id int NOT NULL,
  product_id int NOT NULL,
  quantity int NULL DEFAULT ((1)),
  total_price decimal NULL,
  account_info nvarchar(MAX) NULL,
  status nvarchar(50) NULL DEFAULT ('completed'),
  created_at datetime NULL,
  updated_at datetime NULL,
  account_username nvarchar(100) NULL,
  account_password nvarchar(100) NULL,
  PRIMARY KEY (id)
);
GO

-- Table: PaymentSettings
IF EXISTS (SELECT * FROM sysobjects WHERE name='PaymentSettings' AND xtype='U') DROP TABLE PaymentSettings;
CREATE TABLE PaymentSettings (
  id int NOT NULL DEFAULT ((1)),
  bank_name nvarchar(100) NULL,
  bank_account nvarchar(50) NULL,
  bank_owner nvarchar(100) NULL,
  momo_phone varchar(20) NULL,
  momo_name nvarchar(100) NULL,
  zalopay_phone varchar(20) NULL,
  zalopay_name nvarchar(100) NULL,
  vnpay_phone varchar(20) NULL,
  vnpay_name nvarchar(100) NULL,
  qr_code_url nvarchar(MAX) NULL,
  created_at datetime NULL DEFAULT (getdate()),
  updated_at datetime NULL,
  chat_bubble_url nvarchar(500) NULL DEFAULT ('contact.html'),
  chat_bubble_active bit NULL DEFAULT ((1)),
  PRIMARY KEY (id)
);
GO

-- Table: Products
IF EXISTS (SELECT * FROM sysobjects WHERE name='Products' AND xtype='U') DROP TABLE Products;
CREATE TABLE Products (
  id int IDENTITY(1,1) NOT NULL,
  name nvarchar(200) NOT NULL,
  slug nvarchar(100) NULL,
  price decimal NULL DEFAULT ((0)),
  stock int NULL DEFAULT ((0)),
  image nvarchar(MAX) NULL,
  category_id int NULL,
  category_slug nvarchar(50) NULL,
  description nvarchar(1000) NULL,
  featured bit NULL DEFAULT ((0)),
  created_at datetime NULL DEFAULT (getdate()),
  updated_at datetime NULL,
  account_username nvarchar(100) NULL,
  account_password nvarchar(100) NULL,
  cost_price decimal(18, 2) NULL DEFAULT ((0)),
  account_type nvarchar(20) NULL DEFAULT ('single'),
  accounts_list nvarchar(MAX) NULL,
  is_hidden bit NULL DEFAULT ((0)),
  created_by int NULL,
  PRIMARY KEY (id)
);
GO

-- Table: Sessions
IF EXISTS (SELECT * FROM sysobjects WHERE name='Sessions' AND xtype='U') DROP TABLE Sessions;
CREATE TABLE Sessions (
  id int IDENTITY(1,1) NOT NULL,
  user_id int NOT NULL,
  token varchar(255) NOT NULL,
  created_at datetime NULL DEFAULT (getdate()),
  expires_at datetime NULL,
  PRIMARY KEY (id)
);
GO

-- Table: Transactions
IF EXISTS (SELECT * FROM sysobjects WHERE name='Transactions' AND xtype='U') DROP TABLE Transactions;
CREATE TABLE Transactions (
  id int IDENTITY(1,1) NOT NULL,
  user_id int NOT NULL,
  type nvarchar(50) NOT NULL,
  amount decimal(18, 2) NOT NULL,
  description nvarchar(500) NULL,
  created_at datetime NULL DEFAULT (getdate()),
  PRIMARY KEY (id)
);
GO

-- Table: Users
IF EXISTS (SELECT * FROM sysobjects WHERE name='Users' AND xtype='U') DROP TABLE Users;
CREATE TABLE Users (
  id int IDENTITY(1,1) NOT NULL,
  name nvarchar(100) NOT NULL,
  email nvarchar(255) NULL,
  password varchar(255) NOT NULL,
  created_at datetime NULL DEFAULT (getdate()),
  updated_at datetime NULL DEFAULT (getdate()),
  balance decimal(18, 2) NULL DEFAULT ((0.00)),
  role nvarchar(20) NULL DEFAULT ('user'),
  phone nvarchar(20) NULL,
  PRIMARY KEY (id)
);
GO

